// =============================================================================
// Kun Like 桌宠 · DSH 1.x 动态插件历史参考（Host 半）
// 2.x 静态 bundle 不加载此文件；当前实现位于 plugin/src/index.ts。
//
// 职责：
//   1. 读取本地素材（精灵图 + 完成音），通过 webServer 注册 HTTP 路由给浏览器加载
//   2. 轮询 agents 服务，按 Agent 的 running → idle 转换推导桌宠状态
//   3. 任务完成时由宿主进程用系统命令播放「你干嘛~哎哟」（全窗口/全会话可闻）
//   4. 提供 pet-state RPC 与 kun_pet_debug 调试工具
//
// 如需研究旧版 cordis_define 载荷，可配合 kunpet.package.json 阅读。
// =============================================================================

// ===== 配置区（按需修改） =====
const CONFIG = {
  // 精灵图路径（8 列 × 9 行、每格 192×208 的 WebP）
  spritePath: '/absolute/path/to/dsh-kun-like-pet/assets/spritesheet.webp',
  // 任务完成提示音路径（mp3）
  voicePath: '/absolute/path/to/dsh-kun-like-pet/assets/voice.mp3',
  // 宿主进程系统级播放命令（macOS 用 afplay；Windows 可用 powershell -c (New-Object Media.SoundPlayer '...').PlaySync()；Linux 可用 ffplay -nodisp -autoexit）
  playCommand: (path) => "afplay '" + path.replace(/'/g, "'\\''") + "'",
  // 状态轮询间隔（毫秒）
  pollMs: 500,
  // 庆祝动画持续时长（毫秒）
  celebrateMs: 4800,
  // 失败动画持续时长（毫秒）
  failedMs: 2600,
}

return {
  inject: ['timer'],
  apply(ctx) {
    const fs = ctx.get('fs')
    const webServer = ctx.get('webServer')
    if (fs === undefined || webServer === undefined) {
      console.error('[kun-pet] fs or webServer service is unavailable')
      return
    }

    // ---------- load pet assets once ----------
    let spriteBytes = null
    let voiceBytes = null
    let disposed = false
    const routeDisposers = []

    const registerRoutes = () => {
      if (spriteBytes !== null) {
        routeDisposers.push(webServer.register({
          kind: 'exact',
          path: '/kun-pet/spritesheet.webp',
          handler: (req, res) => {
            res.writeHead(200, {
              'Content-Type': 'image/webp',
              'Content-Length': String(spriteBytes.length),
              'Cache-Control': 'public, max-age=86400',
            })
            res.end(spriteBytes)
          },
        }))
      }
      if (voiceBytes !== null) {
        routeDisposers.push(webServer.register({
          kind: 'exact',
          path: '/kun-pet/voice.mp3',
          handler: (req, res) => {
            res.writeHead(200, {
              'Content-Type': 'audio/mpeg',
              'Content-Length': String(voiceBytes.length),
              'Cache-Control': 'public, max-age=86400',
            })
            res.end(voiceBytes)
          },
        }))
      }
    }

    const loadAssets = async () => {
      try {
        const target = await fs.resolve(CONFIG.spritePath)
        spriteBytes = await fs.readBytes(target, undefined, 16 * 1024 * 1024)
        console.log('[kun-pet] spritesheet loaded:', spriteBytes.length, 'bytes')
      } catch (err) {
        console.error('[kun-pet] failed to load spritesheet:', err)
      }
      try {
        const target = await fs.resolve(CONFIG.voicePath)
        voiceBytes = await fs.readBytes(target, undefined, 8 * 1024 * 1024)
        console.log('[kun-pet] voice loaded:', voiceBytes.length, 'bytes')
      } catch (err) {
        console.error('[kun-pet] failed to load voice:', err)
      }
      if (!disposed) registerRoutes()
    }
    const assetsReady = loadAssets()

    // ---------- pet state machine (polling-driven) ----------
    let mode = 'idle'
    let seq = 0
    let celebrating = false
    let celebrateTimer = null
    let failTimer = null
    let celebrateCount = 0
    let workMarks = 0
    let errorMarks = 0
    let transitionsSeen = 0
    let pollCount = 0
    let rawExecute = 0
    let rawApproval = 0
    let rawRequestError = 0
    let toolsInFlight = 0
    let recentTool = false
    let recentToolTimer = null
    let waitingCount = 0
    let lastAgentStatuses = []
    let lastPlayError = null

    const turnFlags = new WeakMap() // agent -> { worked, errored }
    const lastStatus = new WeakMap() // agent -> 'idle' | 'running'
    const observedAgents = new Set()
    let flagEntries = 0
    const flagsOf = (agent) => {
      let f = turnFlags.get(agent)
      if (f === undefined) {
        f = { worked: false, errored: false }
        turnFlags.set(agent, f)
        flagEntries++
      }
      return f
    }

    const lastStatusEntries = () => {
      const out = []
      for (const agent of observedAgents) {
        const s = lastStatus.get(agent)
        if (s !== undefined) out.push([agent, s])
      }
      return out
    }

    const currentRunningCount = () => {
      let n = 0
      for (const entry of lastStatusEntries()) {
        if (entry[1] === 'running') n++
      }
      return n
    }

    const setMode = (next) => {
      if (next === mode) return
      if (celebrating && next !== 'celebrating') return
      mode = next
      seq++
    }

    const deriveMode = (runningCount) => {
      if (celebrating) return
      let next
      if (waitingCount > 0) next = 'waiting'
      else if (runningCount > 0) next = (toolsInFlight > 0 || recentTool) ? 'working' : 'review'
      else next = 'idle'
      setMode(next)
    }

    const playSystemVoice = () => {
      const shell = ctx.get('shell')
      if (shell === undefined) {
        lastPlayError = 'shell service unavailable'
        return
      }
      try {
        const spec = shell.resolve({ command: CONFIG.playCommand(CONFIG.voicePath) })
        shell.run(spec).catch((err) => {
          lastPlayError = String(err && err.message ? err.message : err)
        })
        lastPlayError = null
      } catch (err) {
        lastPlayError = String(err && err.message ? err.message : err)
        console.error('[kun-pet] failed to start voice playback:', err)
      }
    }

    const celebrate = () => {
      if (celebrating) {
        // Extend the ongoing celebration; never double-fire the sound.
        if (celebrateTimer) celebrateTimer()
        celebrateTimer = ctx.timeout(() => {
          celebrateTimer = null
          celebrating = false
          deriveMode(currentRunningCount())
        }, CONFIG.celebrateMs)
        return
      }
      celebrateCount++
      celebrating = true
      setMode('celebrating')
      playSystemVoice()
      celebrateTimer = ctx.timeout(() => {
        celebrateTimer = null
        celebrating = false
        deriveMode(currentRunningCount())
      }, CONFIG.celebrateMs)
    }

    const showFailed = () => {
      if (celebrating) return
      setMode('failed')
      if (failTimer) failTimer()
      failTimer = ctx.timeout(() => {
        failTimer = null
        deriveMode(currentRunningCount())
      }, CONFIG.failedMs)
    }

    const markToolSettled = (wasQuestion) => {
      toolsInFlight = Math.max(0, toolsInFlight - 1)
      if (wasQuestion) {
        waitingCount = Math.max(0, waitingCount - 1)
      }
      if (toolsInFlight === 0) {
        if (recentToolTimer) recentToolTimer()
        recentToolTimer = ctx.timeout(() => {
          recentToolTimer = null
          recentTool = false
          deriveMode(currentRunningCount())
        }, 2500)
      }
      deriveMode(currentRunningCount())
    }

    ctx.effect(() => () => {
      disposed = true
      for (const d of routeDisposers) d()
      if (celebrateTimer) celebrateTimer()
      if (failTimer) failTimer()
      if (recentToolTimer) recentToolTimer()
    })

    // ---------- polling: live agent statuses ----------
    const agentsService = ctx.get('agents')
    const poll = () => {
      pollCount++
      if (agentsService === undefined) return
      let list
      try {
        list = agentsService.list()
      } catch (err) {
        return
      }
      if (!Array.isArray(list)) return
      const runningNow = new Set()
      const statuses = []
      for (const agent of list) {
        let status = 'idle'
        try {
          status = agent && agent.status === 'running' ? 'running' : 'idle'
        } catch (err) {
          status = 'idle'
        }
        statuses.push(status)
        if (status === 'running') runningNow.add(agent)
        const prev = lastStatus.get(agent)
        lastStatus.set(agent, status)
        if (agent && prev === undefined) observedAgents.add(agent)
        if (prev === 'running' && status === 'idle') {
          transitionsSeen++
          if (runningNow.size === 0 && waitingCount === 0) {
            const f = turnFlags.get(agent)
            if (f === undefined || !f.errored) celebrate()
            if (f !== undefined) {
              turnFlags.delete(agent)
              flagEntries--
            }
          }
        }
      }
      lastAgentStatuses = statuses
      deriveMode(runningNow.size)
    }
    const stopPolling = ctx.interval(poll, CONFIG.pollMs)
    ctx.effect(() => stopPolling)

    // ---------- waterfalls (waiting + errors) ----------
    ctx.on('approval/request', (req, next) => {
      rawApproval++
      waitingCount++
      deriveMode(currentRunningCount())
      let p
      try {
        p = Promise.resolve(next())
      } catch (err) {
        waitingCount = Math.max(0, waitingCount - 1)
        deriveMode(currentRunningCount())
        throw err
      }
      p.then(
        () => { waitingCount = Math.max(0, waitingCount - 1); deriveMode(currentRunningCount()) },
        () => { waitingCount = Math.max(0, waitingCount - 1); deriveMode(currentRunningCount()) },
      )
      return p
    })

    ctx.on('tools/execute', (exec, next) => {
      rawExecute++
      let isQuestion = false
      if (exec && exec.agent) {
        flagsOf(exec.agent).worked = true
        workMarks++
      }
      if (exec && typeof exec.name === 'string' && exec.name === 'ask_user_question') {
        isQuestion = true
        waitingCount++
      }
      toolsInFlight++
      recentTool = true
      if (recentToolTimer) {
        recentToolTimer()
        recentToolTimer = null
      }
      deriveMode(currentRunningCount())
      let p
      try {
        p = Promise.resolve(next())
      } catch (err) {
        markToolSettled(isQuestion)
        throw err
      }
      p.then(
        () => markToolSettled(isQuestion),
        () => markToolSettled(isQuestion),
      )
      return p
    })

    ctx.on('agent/request-error', (payload, next) => {
      rawRequestError++
      if (payload && payload.agent) {
        flagsOf(payload.agent).errored = true
        errorMarks++
      }
      showFailed()
      return next()
    })

    // ---------- client RPC ----------
    harness.handle('pet-state', async () => {
      await assetsReady
      const host = webServer.host === '0.0.0.0' ? '127.0.0.1' : webServer.host
      const base = 'http://' + host + ':' + webServer.port
      return {
        mode,
        seq,
        spriteUrl: spriteBytes !== null ? base + '/kun-pet/spritesheet.webp' : null,
        voiceUrl: voiceBytes !== null ? base + '/kun-pet/voice.mp3' : null,
      }
    })

    // ---------- debug tool ----------
    harness.registerTool(ctx, harness.defineTool({
      name: 'kun_pet_debug',
      description: 'Read the Kun Like desktop-pet state machine internals and polling counters. Use only to diagnose pet behavior.',
      parameters: {},
      output: {
        schema: { type: 'json' },
        render: (_args, value) => [{ type: 'text', text: JSON.stringify(value, null, 2) }],
      },
      execute() {
        return Promise.resolve({
          mode,
          seq,
          celebrating,
          celebrateCount,
          workMarks,
          errorMarks,
          transitionsSeen,
          flagEntries,
          waitingCount,
          toolsInFlight,
          recentTool,
          pollCount,
          agentCount: lastAgentStatuses.length,
          lastAgentStatuses,
          lastPlayError,
          raw: {
            execute: rawExecute,
            approval: rawApproval,
            requestError: rawRequestError,
          },
        })
      },
    }))
  },
}

code.client:
// =============================================================================
// Kun Like 桌宠 · DSH 动态插件（Client 半）
// 用于 DSH 的 cordis_define 工具：code.client 字段
//
// 职责：
//   1. 注入 shell.overlay 插槽，在 Web 界面右下角渲染桌宠
//   2. 按 8 列 × 9 行的精灵图契约播放 9 种状态动画（帧序与时长沿用 Codex 契约）
//   3. 支持拖动（跑步动画）、点击（挥手互动 + 浏览器端播放语音）
//   4. 每 400ms 通过 pet-state RPC 同步宿主端状态机
//
// 说明：任务完成的声音由 Host 端系统级播放（见 src/host.js），
//       客户端只在「点击互动」时用浏览器 Audio 播放，避免双响。
// =============================================================================

return {
  inject: ['timer'],
  apply(ctx) {
    const slots = ctx.get('slots')
    if (slots === undefined) return

    styles.insert(`
.kun-pet-bubble {
  position: absolute;
  left: 50%;
  bottom: 100%;
  margin-bottom: 12px;
  transform: translateX(-50%);
  background: rgba(255, 255, 255, 0.96);
  color: #333333;
  border: 1px solid rgba(0, 0, 0, 0.08);
  border-radius: 12px;
  padding: 6px 12px;
  font-size: 13px;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  white-space: nowrap;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.14);
  pointer-events: none;
  z-index: 2;
}
.kun-pet-bubble::after {
  content: '';
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  border: 7px solid transparent;
  border-top-color: rgba(255, 255, 255, 0.96);
}
`)

    const CW = 192
    const CH = 208
    const SCALE = 0.85
    const W = CW * SCALE
    const H = CH * SCALE

    // 8 列 × 9 行精灵图契约：每行一种状态动画（帧时长单位 ms）
    const ROWS = {
      idle: { row: 0, count: 6, frames: [280, 110, 110, 140, 140, 320] },
      runRight: { row: 1, count: 8, frames: [120, 120, 120, 120, 120, 120, 120, 220] },
      runLeft: { row: 2, count: 8, frames: [120, 120, 120, 120, 120, 120, 120, 220] },
      wave: { row: 3, count: 4, frames: [140, 140, 140, 280] },
      jump: { row: 4, count: 5, frames: [140, 140, 140, 140, 280] },
      failed: { row: 5, count: 8, frames: [140, 140, 140, 140, 140, 140, 140, 240] },
      waiting: { row: 6, count: 6, frames: [150, 150, 150, 150, 150, 260] },
      working: { row: 7, count: 6, frames: [120, 120, 120, 120, 120, 220] },
      review: { row: 8, count: 6, frames: [150, 150, 150, 150, 150, 280] },
    }

    const MODE_ANIM = {
      idle: 'idle',
      working: 'working',
      review: 'review',
      waiting: 'waiting',
      failed: 'failed',
      celebrating: 'wave',
    }

    const BUBBLES = {
      idle: '休息中~ 有事叫我',
      working: '努力工作中…',
      review: '思考中…',
      waiting: '在等你回复哦~',
      failed: '呜…出错了 (._.)',
      celebrating: '完成啦！你干嘛~哎哟',
      dragging: '呜哇~ 别拽我！',
      poke: '诶嘿~',
    }

    let celebrateFlip = 0
    let lastCelebrateSeq = -1
    let dragData = null
    let audioEl = null
    let reactionTimer = null
    let viewportEl = null

    const viewportSize = () => {
      if (viewportEl) {
        const r = viewportEl.getBoundingClientRect()
        if (r.width > 0 && r.height > 0) return { w: r.width, h: r.height }
      }
      return { w: 1400, h: 900 }
    }

    function KunPet() {
      const [st, setSt] = React.useState({ mode: 'idle', seq: -1, spriteUrl: null, voiceUrl: null })
      const [frame, setFrame] = React.useState(0)
      const [pos, setPos] = React.useState(null)
      const [dragging, setDragging] = React.useState(false)
      const [dragDir, setDragDir] = React.useState('runRight')
      const [reaction, setReaction] = React.useState(null)
      const [celebrateAnim, setCelebrateAnim] = React.useState('wave')

      React.useEffect(() => {
        let alive = true
        const sync = async () => {
          try {
            const s = await host.call('pet-state')
            if (!alive || !s) return
            setSt((prev) => {
              const seq = typeof s.seq === 'number' ? s.seq : 0
              if (prev.seq === seq && prev.spriteUrl === s.spriteUrl && prev.voiceUrl === s.voiceUrl) return prev
              return {
                mode: String(s.mode || 'idle'),
                seq,
                spriteUrl: s.spriteUrl || null,
                voiceUrl: s.voiceUrl || null,
              }
            })
          } catch (err) {
            // transient rpc error, retry next tick
          }
        }
        sync()
        const stop = ctx.interval(sync, 400)
        return () => { alive = false; stop() }
      }, [])

      const playVoice = () => {
        if (!audioEl || !st.voiceUrl) return
        try {
          audioEl.currentTime = 0
          const p = audioEl.play()
          if (p && typeof p.catch === 'function') p.catch(() => {})
        } catch (err) {
          // autoplay may be blocked until the first user gesture
        }
      }

      const doReaction = (animName, ms) => {
        setReaction(animName)
        if (reactionTimer) reactionTimer()
        reactionTimer = ctx.timeout(() => {
          reactionTimer = null
          setReaction(null)
        }, ms)
      }

      // Celebration sound is played by the HOST (system-wide afplay), so the
      // client only animates here — no double playback.
      React.useEffect(() => {
        if (st.mode !== 'celebrating' || st.seq === lastCelebrateSeq) return
        lastCelebrateSeq = st.seq
        celebrateFlip = celebrateFlip + 1
        setCelebrateAnim(celebrateFlip % 2 === 0 ? 'jump' : 'wave')
      }, [st.mode, st.seq])

      React.useEffect(() => () => {
        if (reactionTimer) reactionTimer()
      }, [])

      let anim
      let bubble
      if (dragging) {
        anim = dragDir
        bubble = BUBBLES.dragging
      } else if (reaction) {
        anim = reaction
        bubble = BUBBLES.poke
      } else if (st.mode === 'celebrating') {
        anim = celebrateAnim
        bubble = BUBBLES.celebrating
      } else {
        anim = MODE_ANIM[st.mode] || 'idle'
        bubble = BUBBLES[st.mode] || BUBBLES.idle
      }
      const spec = ROWS[anim] || ROWS.idle

      React.useEffect(() => {
        setFrame(0)
        let disposed = false
        let stopTimer = null
        const step = (i) => {
          if (disposed) return
          setFrame(i)
          const delay = spec.frames[i] || 150
          stopTimer = ctx.timeout(() => step((i + 1) % spec.count), delay)
        }
        step(0)
        return () => {
          disposed = true
          if (stopTimer) stopTimer()
        }
      }, [anim])

      const onPointerDown = (e) => {
        if (typeof e.button === 'number' && e.button !== 0) return
        const el = e.currentTarget
        try { el.setPointerCapture(e.pointerId) } catch (err) { /* ignore */ }
        const rect = el.getBoundingClientRect()
        dragData = {
          x: e.clientX,
          y: e.clientY,
          left: rect.left,
          top: rect.top,
          moved: false,
        }
        setDragging(true)
      }

      const onPointerMove = (e) => {
        if (!dragData) return
        const dx = e.clientX - dragData.x
        const dy = e.clientY - dragData.y
        if (Math.abs(dx) > 4 || Math.abs(dy) > 4) dragData.moved = true
        if (dx > 4) setDragDir('runRight')
        else if (dx < -4) setDragDir('runLeft')
        const vp = viewportSize()
        const left = Math.min(Math.max(dragData.left + dx, -W * 0.7), vp.w - W * 0.3)
        const top = Math.min(Math.max(dragData.top + dy, -H * 0.5), vp.h - H * 0.5)
        setPos({ left, top })
      }

      const onPointerEnd = () => {
        const d = dragData
        dragData = null
        setDragging(false)
        if (d && !d.moved) {
          doReaction('wave', 2400)
          playVoice()
        }
      }

      const col = frame % spec.count
      const bgX = -(col * W)
      const bgY = -(spec.row * H)

      const wrapStyle = {
        position: 'fixed',
        width: W,
        height: H,
        zIndex: 1000,
        pointerEvents: 'auto',
        userSelect: 'none',
        WebkitUserSelect: 'none',
        touchAction: 'none',
      }
      if (pos) {
        wrapStyle.left = pos.left
        wrapStyle.top = pos.top
      } else {
        wrapStyle.right = 20
        wrapStyle.bottom = 20
      }

      const spriteStyle = {
        position: 'absolute',
        left: 0,
        top: 0,
        width: W,
        height: H,
        backgroundImage: st.spriteUrl ? 'url("' + st.spriteUrl + '")' : 'none',
        backgroundSize: String(W * 8) + 'px ' + String(H * 9) + 'px',
        backgroundPosition: String(bgX) + 'px ' + String(bgY) + 'px',
        backgroundRepeat: 'no-repeat',
        imageRendering: 'pixelated',
        cursor: dragging ? 'grabbing' : 'grab',
      }

      const children = [
        st.spriteUrl
          ? React.createElement('div', { key: 'sprite', style: spriteStyle })
          : React.createElement('div', {
              key: 'emoji',
              style: { position: 'absolute', left: 0, top: 0, width: W, height: H, fontSize: 110, lineHeight: 1.6, textAlign: 'center' },
            }, '🐤'),
        React.createElement('div', { key: 'bubble', className: 'kun-pet-bubble' }, bubble),
        React.createElement('div', {
          key: 'viewport',
          ref: (el) => { viewportEl = el },
          style: {
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            pointerEvents: 'none',
            visibility: 'hidden',
          },
        }),
      ]
      if (st.voiceUrl) {
        children.push(React.createElement('audio', {
          key: 'voice',
          src: st.voiceUrl,
          preload: 'auto',
          ref: (el) => { audioEl = el },
        }))
      }

      return React.createElement('div', {
        onPointerDown,
        onPointerMove,
        onPointerUp: onPointerEnd,
        onPointerCancel: onPointerEnd,
        style: wrapStyle,
        title: 'Kun Like 桌宠 · 拖动移动 · 点击互动',
      }, children)
    }

    slots.inject('shell.overlay', () => slots.register(
      { name: 'shell.overlay', id: 'kun-pet', order: 100, label: 'Kun Like 桌宠' },
      () => React.createElement(KunPet),
    ))
  },
}
